import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"Tauri 迁移 Electron 调研索引","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/07-electron-migration-research.md","filePath":"desktop/07-electron-migration-research.md","lastUpdated":1780324996000}'),s={name:"desktop/07-electron-migration-research.md"};function r(d,e,c,l,n,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="tauri-迁移-electron-调研索引" tabindex="-1">Tauri 迁移 Electron 调研索引 <a class="header-anchor" href="#tauri-迁移-electron-调研索引" aria-label="Permalink to &quot;Tauri 迁移 Electron 调研索引&quot;">​</a></h1><blockquote><p>日期：2026-05-31 范围：桌面端壳层从 Tauri 2 迁移到 Electron，React/Vite 渲染层尽量复用。 状态：调研与迁移方案，不是最终实现说明。</p></blockquote><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>迁移方向可行，但不能按“把 Tauri 项目换成 Electron 模板”处理。当前桌面端把 Tauri 2 当作完整 host runtime 使用：它负责自动更新、系统通知、文件选择、外链打开、窗口/托盘/菜单、子进程 sidecar、PTY 终端、子 WebView 预览面板、应用模式配置、窗口状态持久化和权限白名单。React 页面主体可以复用，但必须先把 <code>desktop/src</code> 里的 <code>@tauri-apps/*</code> 直接调用收敛为一层 <code>desktopHost</code> adapter，然后再并行保留 Tauri 实现和新增 Electron 实现。</p><p>推荐目标架构是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>desktop/src React renderer</span></span>
<span class="line"><span>  -&gt; desktop/src/lib/desktopHost/* typed host adapter</span></span>
<span class="line"><span>  -&gt; Tauri implementation during transition</span></span>
<span class="line"><span>  -&gt; Electron preload contextBridge implementation</span></span>
<span class="line"><span>  -&gt; Electron main process services</span></span>
<span class="line"><span>       - sidecar manager</span></span>
<span class="line"><span>       - updater service</span></span>
<span class="line"><span>       - notification service</span></span>
<span class="line"><span>       - dialog/open service</span></span>
<span class="line"><span>       - window/tray/menu service</span></span>
<span class="line"><span>       - terminal/pty service</span></span>
<span class="line"><span>       - preview WebContentsView service</span></span></code></pre></div><p>这样可以让前端继续用同一套 Zustand store、API client、WebSocket 和组件测试，同时把高风险系统能力迁移压缩到 adapter contract 和 Electron main/preload 层。不要把本地 Bun server 合并进 Electron main，也不要把 renderer 从 HTTP/WebSocket 改成全 IPC；现有 <code>desktop/src/api/*</code>、<code>chatStore</code>、<code>workspacePanelStore</code>、<code>teamStore</code> 已经围绕 local server contract 做了重连、去重、流式 flush 和多客户端观察，这些成熟行为应作为迁移边界保留。</p><h2 id="外部依据" tabindex="-1">外部依据 <a class="header-anchor" href="#外部依据" aria-label="Permalink to &quot;外部依据&quot;">​</a></h2><p>本次调研以官方文档和 GitHub issue 为准，Twitter/X 搜索结果信噪比较低，未作为决策依据。</p><ul><li>Tauri README 明确 Tauri 通过 WRY 使用系统 WebView：macOS/iOS 是 WKWebView，Windows 是 WebView2，Linux 是 WebKitGTK；同时 Tauri 提供 bundler、自更新、托盘和原生通知等桌面能力。参考：<a href="https://github.com/tauri-apps/tauri" target="_blank" rel="noreferrer">tauri-apps/tauri</a>。</li><li>Tauri 2 updater 插件使用 endpoint/static JSON 和 capability permission；危险命令默认阻断，必须在 capabilities 里放行。参考：<a href="https://v2.tauri.app/plugin/updater/" target="_blank" rel="noreferrer">Tauri Updater</a>。</li><li>Tauri capability 是按 window/webview 授权的权限集合，权限名使用 <code>plugin:permission</code> 形式。参考：<a href="https://v2.tauri.app/reference/acl/capability/" target="_blank" rel="noreferrer">Tauri Capability</a>。</li><li>Electron 推荐使用 preload + <code>contextBridge</code>，不要把 <code>ipcRenderer</code> 原样暴露给 renderer；<code>contextIsolation</code> 从 Electron 12 起默认启用。参考：<a href="https://www.electronjs.org/docs/latest/tutorial/context-isolation" target="_blank" rel="noreferrer">Electron Context Isolation</a> 与 <a href="https://www.electronjs.org/docs/latest/tutorial/security" target="_blank" rel="noreferrer">Electron Security</a>。</li><li>Electron 内置 <code>autoUpdater</code> 不支持 Linux；如果要覆盖 macOS/Windows/Linux，更适合用 <code>electron-builder</code> + <code>electron-updater</code>。参考：<a href="https://www.electronjs.org/docs/api/auto-updater/" target="_blank" rel="noreferrer">Electron autoUpdater</a> 与 <a href="https://www.electron.build/docs/features/auto-update" target="_blank" rel="noreferrer">electron-builder Auto Update</a>。</li><li>Electron <code>BrowserView</code> 已弃用，应使用 <code>WebContentsView</code> 承载内嵌浏览器/预览面板。参考：<a href="https://www.electronjs.org/docs/latest/api/browser-view" target="_blank" rel="noreferrer">Electron BrowserView</a>。</li><li>Tauri 社区 issue 里也能看到系统 WebView 的真实世界差异，例如 macOS WebView 特定异常和 WebKit memory/performance 争议。参考：<a href="https://github.com/tauri-apps/tauri/issues/13141" target="_blank" rel="noreferrer">tauri #13141</a>、<a href="https://github.com/tauri-apps/tauri/issues/5889" target="_blank" rel="noreferrer">tauri #5889</a>。</li></ul><h2 id="本仓库现状" tabindex="-1">本仓库现状 <a class="header-anchor" href="#本仓库现状" aria-label="Permalink to &quot;本仓库现状&quot;">​</a></h2><h3 id="桌面三层" tabindex="-1">桌面三层 <a class="header-anchor" href="#桌面三层" aria-label="Permalink to &quot;桌面三层&quot;">​</a></h3><ul><li>React/Vite renderer：<code>desktop/src</code>。</li><li>Tauri host：<code>desktop/src-tauri</code>。</li><li>本地 server/CLI sidecar：<code>desktop/sidecars/claude-sidecar.ts</code> 打包成 <code>desktop/src-tauri/binaries/claude-sidecar-*</code>，再由 Tauri host 启动。</li></ul><p>迁移后仍应保留这个三层关系，只把中间 host 从 Tauri 改成 Electron：</p><ul><li>React renderer 继续调用 <code>desktop/src/api/client.ts</code>、<code>sessionsApi</code>、<code>teamsApi</code>、WebSocket manager。</li><li>Electron main 负责启动和监管 local server sidecar。</li><li>renderer 通过 <code>getServerUrl</code> 得到 local server URL，而不是直接通过 IPC 读写会话数据。</li></ul><p>关键入口：</p><ul><li><code>desktop/src-tauri/src/lib.rs</code> 注册 Tauri plugins、commands、tray/menu、sidecar、terminal、update 准备、通知 bridge、窗口生命周期。</li><li><code>desktop/src-tauri/capabilities/default.json</code> 声明 Tauri 2 权限。</li><li><code>desktop/src-tauri/tauri.conf.json</code> 声明窗口、CSP、updater、bundle、externalBin、icons。</li><li><code>desktop/src/lib/desktopRuntime.ts</code> 解析 Tauri runtime 并获取 local server URL。</li><li><code>desktop/src/stores/updateStore.ts</code> 管理自动更新状态机。</li><li><code>desktop/src/lib/desktopNotifications.ts</code> 管理通知权限、发送、点击回跳和系统设置入口。</li><li><code>desktop/src/api/terminal.ts</code> 通过 Tauri command + event 管理 PTY。</li><li><code>desktop/src/lib/previewBridge.ts</code> 和 <code>desktop/src-tauri/src/webview_panel.rs</code> 管理内嵌预览 WebView。</li></ul><h3 id="当前性能背景" tabindex="-1">当前性能背景 <a class="header-anchor" href="#当前性能背景" aria-label="Permalink to &quot;当前性能背景&quot;">​</a></h3><p><code>SCROLL_PERF_INVESTIGATION.md</code> 的关键判断是：卡顿主要来自 macOS Tauri 使用 WKWebView，而 Electron 固定 Chromium/Blink。已合并的 <code>content-visibility:auto</code> 是 WebKit 侧缓解方案，但如果目标是接近 CodeX/官方 Claude Code 的一致滚动性能，Electron 是合理方向。迁移收益是可控渲染栈和跨平台一致性；成本是安装体积、内存、签名更新链路和安全边界全部要重建。</p><h2 id="tauri-2-能力盘点与-electron-对照" tabindex="-1">Tauri 2 能力盘点与 Electron 对照 <a class="header-anchor" href="#tauri-2-能力盘点与-electron-对照" aria-label="Permalink to &quot;Tauri 2 能力盘点与 Electron 对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>当前 Tauri 位置</th><th>Electron 目标</th><th>迁移风险</th></tr></thead><tbody><tr><td>自动更新</td><td><code>tauri.conf.json</code> <code>plugins.updater</code>、<code>updateStore.ts</code>、<code>prepare_for_update_install</code>、<code>tauri.release-ci.json</code></td><td><code>electron-builder</code> + <code>electron-updater</code>，main process 暴露 <code>check/download/install/relaunch</code> IPC</td><td>签名、feed metadata、Windows sidecar 文件锁、Linux update 支持不能照搬</td></tr><tr><td>通知</td><td><code>tauri-plugin-notification</code>、<code>desktopNotifications.ts</code>、<code>macos_notifications.m</code></td><td>Electron <code>Notification</code> + main process click routing，必要时保留 macOS native bridge</td><td>macOS 权限状态和点击回跳语义必须回归测试</td></tr><tr><td>文件/目录选择</td><td><code>@tauri-apps/plugin-dialog.open/save</code></td><td><code>dialog.showOpenDialog/showSaveDialog</code></td><td>从 Tauri capability 变成自管 IPC 白名单，路径和 options 要验证</td></tr><tr><td>外链/系统打开</td><td><code>@tauri-apps/plugin-shell.open</code></td><td><code>shell.openExternal/openPath</code></td><td>必须限制 URL scheme，避免 renderer 任意打开危险目标</td></tr><tr><td>sidecar</td><td>Tauri shell plugin + <code>start_server_sidecar</code> / <code>spawn_and_track_adapters_sidecar</code></td><td>Electron main <code>child_process.spawn</code> + sidecar manager</td><td>动态端口、启动日志、adapter 重启、Windows kill 逻辑必须等价</td></tr><tr><td>PTY 终端</td><td>Rust <code>portable-pty</code> commands + Tauri events</td><td>Electron main 继续用 Node/Rust sidecar/原生模块之一提供 PTY</td><td>如果从 Rust 移到 Node，shell 解析和 Windows 行为会变</td></tr><tr><td>窗口/托盘/菜单</td><td><code>setup_system_tray</code>、macOS <code>MenuBuilder</code>、<code>RunEvent</code></td><td><code>BrowserWindow</code>、<code>Tray</code>、<code>Menu</code>、<code>app</code> lifecycle</td><td>关闭隐藏到托盘、macOS reopen、窗口位置恢复必须逐平台验证</td></tr><tr><td>窗口控制/拖拽</td><td><code>getCurrentWindow().minimize/toggleMaximize/close/startDragging</code></td><td>preload bridge 到 <code>BrowserWindow</code> actions</td><td>自定义标题栏和拖拽区域需要真实窗口 smoke</td></tr><tr><td>子 WebView 预览</td><td>Tauri <code>WebviewBuilder.add_child</code> + <code>preview_*</code> commands</td><td><code>WebContentsView</code>，renderer 只发 typed IPC</td><td><code>BrowserView</code> 已弃用，URL 白名单和消息 JSON 校验必须保留</td></tr><tr><td>单实例</td><td><code>tauri_plugin_single_instance</code></td><td><code>app.requestSingleInstanceLock()</code></td><td>第二实例参数、显示主窗口、协议启动要补测试</td></tr><tr><td>app mode / portable config</td><td><code>get_app_mode</code>、<code>set_app_mode</code>、<code>detect_portable_dir</code>、<code>CLAUDE_CONFIG_DIR</code></td><td>main process config service</td><td>这是持久化形状变更，要跑 persistence upgrade gate</td></tr><tr><td>zoom</td><td><code>set_app_zoom</code></td><td><code>webContents.setZoomFactor</code></td><td>范围 clamp 和设置页行为要保持</td></tr><tr><td>权限模型</td><td><code>capabilities/default.json</code></td><td>自定义 IPC capability registry</td><td>这是安全边界，不能让 renderer 直接拿 Node/Electron API</td></tr></tbody></table><h2 id="react-可复用边界" tabindex="-1">React 可复用边界 <a class="header-anchor" href="#react-可复用边界" aria-label="Permalink to &quot;React 可复用边界&quot;">​</a></h2><p>可复用：</p><ul><li><code>desktop/src/components/**</code> 中大部分聊天、设置、任务、workspace、markdown、browser UI。</li><li><code>desktop/src/stores/**</code> 的业务状态机，前提是依赖 host 能力的 store 改成调用 adapter。</li><li><code>desktop/src/api/**</code> 的 HTTP/WebSocket client。</li><li><code>desktop/scripts/build-preview-agent.ts</code>、<code>desktop/scripts/build-sidecars.ts</code> 的 sidecar 编译逻辑。</li><li><code>scripts/quality-gate/**</code> 的报告和 lane 框架。</li></ul><p>必须抽象：</p><ul><li>runtime 探测：<code>isTauriRuntime()</code> 需要替换为 <code>getDesktopHostKind()</code>，支持 <code>browser</code>、<code>tauri</code>、<code>electron</code>。</li><li>command 调用：<code>invoke(&#39;...&#39;)</code> 改为 typed host methods。</li><li>event 订阅：Tauri <code>listen(...)</code> 改为 typed <code>desktopHost.events.on(...)</code>。</li><li>shell/dialog/notification/update/window/preview/terminal：全部通过 adapter 暴露。</li></ul><p>不应复用为最终形态：</p><ul><li><code>desktop/src-tauri/**</code> 的 Tauri 配置和 Rust host crate。</li><li>Tauri capability JSON。Electron 需要等价的 IPC allowlist，但不是同一格式。</li><li><code>tauri-apps/tauri-action</code> 和 <code>tauri build</code> CI 步骤。</li></ul><p>必须避免的重写：</p><ul><li>不重写 <code>desktop/src/api/websocket.ts</code> 的重连、退避、ping 和 pending queue。</li><li>不重写 <code>chatStore</code> 的历史加载去重和 streaming flush。</li><li>不重写 workspace 请求的 latest-request 防陈旧覆盖。</li><li>不把 session/team/workspace API 从 HTTP/WS 改成 Electron IPC。</li></ul><h2 id="推荐迁移路径" tabindex="-1">推荐迁移路径 <a class="header-anchor" href="#推荐迁移路径" aria-label="Permalink to &quot;推荐迁移路径&quot;">​</a></h2><h3 id="1-冻结基线" tabindex="-1">1. 冻结基线 <a class="header-anchor" href="#1-冻结基线" aria-label="Permalink to &quot;1. 冻结基线&quot;">​</a></h3><p>先在现有 Tauri 实现上跑并记录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:policy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:coverage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-live</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider-model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">provider:model[:label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>目的不是证明迁移完成，而是固定“现有能力本来是什么状态”。</p><h3 id="2-新增-host-adapter但-tauri-仍是唯一实现" tabindex="-1">2. 新增 host adapter，但 Tauri 仍是唯一实现 <a class="header-anchor" href="#2-新增-host-adapter但-tauri-仍是唯一实现" aria-label="Permalink to &quot;2. 新增 host adapter，但 Tauri 仍是唯一实现&quot;">​</a></h3><p>新建建议路径：</p><ul><li><code>desktop/src/lib/desktopHost/types.ts</code></li><li><code>desktop/src/lib/desktopHost/index.ts</code></li><li><code>desktop/src/lib/desktopHost/tauriHost.ts</code></li><li><code>desktop/src/lib/desktopHost/browserHost.ts</code></li><li><code>desktop/src/lib/desktopHost/__tests__/contract.test.ts</code></li></ul><p>先把 renderer 中直接 import <code>@tauri-apps/*</code> 的位置迁走。完成标准：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@tauri-apps|invoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">(|getCurrentWindow&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop/src</span></span></code></pre></div><p>生产代码中除 <code>desktopHost/tauriHost.ts</code> 外不应再命中。</p><h3 id="3-增加-electron-壳" tabindex="-1">3. 增加 Electron 壳 <a class="header-anchor" href="#3-增加-electron-壳" aria-label="Permalink to &quot;3. 增加 Electron 壳&quot;">​</a></h3><p>建议新增：</p><ul><li><code>desktop/electron/main.ts</code></li><li><code>desktop/electron/preload.ts</code></li><li><code>desktop/electron/services/sidecarManager.ts</code></li><li><code>desktop/electron/services/updater.ts</code></li><li><code>desktop/electron/services/notifications.ts</code></li><li><code>desktop/electron/services/dialogs.ts</code></li><li><code>desktop/electron/services/windows.ts</code></li><li><code>desktop/electron/services/preview.ts</code></li><li><code>desktop/electron/ipc/capabilities.ts</code></li></ul><p>renderer 通过 preload 暴露的 <code>window.desktopHost</code> 调用，不直接使用 Electron API。</p><h3 id="4-构建与发布改造" tabindex="-1">4. 构建与发布改造 <a class="header-anchor" href="#4-构建与发布改造" aria-label="Permalink to &quot;4. 构建与发布改造&quot;">​</a></h3><p>保留 Vite build、sidecar build、质量门禁骨架，替换 Tauri build：</p><ul><li><code>check:native</code> 改名或重定义为 Electron main/preload compile + package config check。</li><li>新增 <code>check:electron</code>。</li><li><code>release-desktop.yml</code> 从 <code>tauri-action</code> 迁到 <code>electron-builder</code> 的 macOS/Windows/Linux matrix。</li><li><code>scripts/release.ts</code> 从更新 <code>tauri.conf.json</code> / <code>Cargo.toml</code> 改为更新 Electron package/build config。</li></ul><h3 id="5-逐能力迁移和验收" tabindex="-1">5. 逐能力迁移和验收 <a class="header-anchor" href="#5-逐能力迁移和验收" aria-label="Permalink to &quot;5. 逐能力迁移和验收&quot;">​</a></h3><p>每迁移一个能力都要满足三层证据：</p><ol><li>contract/unit test 通过；</li><li>Electron main/preload 实现测试通过；</li><li>打包 app smoke 通过。</li></ol><p>不要等到全部迁移完才第一次打开 Electron app。</p><h2 id="安全设计要求" tabindex="-1">安全设计要求 <a class="header-anchor" href="#安全设计要求" aria-label="Permalink to &quot;安全设计要求&quot;">​</a></h2><p>Electron 迁移最大的安全风险不是 Electron 本身，而是从 Tauri 声明式 capability 退化成“renderer 想要什么就 IPC 什么”。必须建立等价能力层：</p><ul><li>renderer 不暴露 Node.js、<code>ipcRenderer</code>、<code>shell</code>、<code>dialog</code>、<code>child_process</code>。</li><li>preload 只暴露固定函数，不暴露通用 invoke/send。</li><li>IPC channel 必须枚举，payload 用 schema 校验。</li><li>shell open 只允许 <code>https:</code>, <code>http:</code>, <code>mailto:</code> 和明确需要的本地 path 打开场景。</li><li>child process 只允许 sidecar 和 PTY 服务，参数白名单要保留 Tauri capability 中的约束。</li><li>preview URL 继续只允许 <code>http/https</code>。</li><li>更新安装前必须停止 sidecar，失败后恢复可重试状态。</li></ul><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to &quot;文档索引&quot;">​</a></h2><ul><li>具体执行任务见：<a href="./08-electron-migration-tasks">Electron 迁移任务清单</a>。</li><li>当前桌面架构见：<a href="./02-architecture">桌面端架构设计</a>。</li><li>当前安装构建见：<a href="./04-installation">安装与构建</a>。</li><li>性能背景见本地文档：<code>SCROLL_PERF_INVESTIGATION.md</code>。</li></ul>`,57)])])}const k=t(s,[["render",r]]);export{u as __pageData,k as default};
